test('ADR047 M1 pi rpc/acp/pane only activates advisor when a non-null cell is present', () => {
  const grants = { advisor: true, extensions: [], tools: [], agents: [], skills: [] }
  const rpc = piRpcSeatParts({ model: 'openai-codex/x', promptFile: '/p', env: { CREW_ADVISOR_MODEL: 'inherited' }, grants, advisorCell: null })
  const acp = acpLaunch({ bin: '/opt/pi/dist/cli.js', model: 'x', promptFile: '/p', cwd: '/tmp', env: {}, grants, advisorCell: null })
  const pane = seatCommand({ role: 'builder', model: 'x', promptFile: '/p', tools: [], deny: '', taskDir: '/tmp', bootBrief: 'b', grants, advisorCell: null })
  assert.equal(rpc.args.some((arg) => arg === PI_ADVISOR_EXTENSION), false)
  assert.equal(acp.args.includes(PI_ADVISOR_EXTENSION), false)
  assert.doesNotMatch(pane, /advisor\.ts/)
  assert.equal(Object.hasOwn(rpc.env, 'CREW_ADVISOR_MODEL'), false)
})

test('ADR047 M2 granted pi commands carry canonical transitional advisor environment', () => {
  const grants = { advisor: true, extensions: [], tools: [], agents: [], skills: [] }
  const advisorCell = { endpoint: '', model: 'anthropic/claude-sonnet-5', models: { 'anthropic/claude-sonnet-5': {} } }
  const rpc = piRpcSeatParts({ model: 'openai-codex/x', promptFile: '/p', env: {}, grants, advisorCell })
  const acp = acpLaunch({ bin: '/opt/pi/dist/cli.js', model: 'x', promptFile: '/p', cwd: '/tmp', env: {}, grants, advisorCell })
  const pane = seatCommand({ role: 'builder', model: 'x', promptFile: '/p', tools: [], deny: '', taskDir: '/tmp', bootBrief: 'b', grants, advisorCell })
  assert.equal(rpc.env.CREW_ADVISOR_MODEL, advisorCell.model)
  assert.equal(rpc.env.CREW_ADVISOR_PROVENANCE, 'seat-transitional')
  assert.equal(acp.env.CREW_ADVISOR_MODEL, advisorCell.model)
  assert.match(pane, /CREW_ADVISOR_MODEL/)
})

